#include <stdio.h>
#include <string.h>
int main() {
    char s[1000]; if (!fgets(s, sizeof(s), stdin)) return 0;
    int len = strlen(s);
    while (len > 0 && (s[len-1] == '\n' || s[len-1] == '\r')) s[--len] = '\0';
    for (int i = 0; i < len; i++) {
        if (strchr("aeiouAEIOU", s[i])) putchar(' ');
        else putchar(s[i]);
    }
    putchar('\n');
    return 0;
}

